import { describe, it } from "vitest";

describe("MHPCO claim office", () => {
  // --- Quote: simplest case and the processing fee ---
  it.todo("quotes an empty item list -- premium 5 G (processing fee only)");

  // --- Quote: base premium catalogue (each type has its own base premium) ---
  it.todo("quotes a single sword -- base premium 100 G + 5 G fee = 105 G");
  it.todo("quotes a single amulet -- base premium 60 G + 5 G fee = 65 G");
  it.todo("quotes a single staff -- base premium 80 G + 5 G fee = 85 G");
  it.todo("quotes a single potion -- base premium 40 G + 5 G fee = 45 G");
  it.todo("quotes a single rune -- component base premium 25 G + 5 G fee = 30 G");
  it.todo("quotes a single moonstone -- component base premium 25 G + 5 G fee = 30 G");

  // --- Quote: component building block of 3 alike components ---
  it.todo("quotes 2 runes -- base premium 50 G (no block)");
  it.todo("quotes 3 runes -- base premium 60 G (block applies)");
  it.todo("quotes 4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block at 7)");
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks by type)");

  // --- Quote: item-specific modifiers ---
  it.todo("quotes a cursed sword -- 50 % curse surcharge on that item's base premium");
  it.todo("quotes a sword with enchantment 5 -- 30 % high-enchantment surcharge applies (threshold is inclusive)");
  it.todo("quotes a sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo("quotes a cursed sword with enchantment 5 -- both curse and high-enchantment surcharges apply");
  it.todo("quotes a cursed sword and a plain amulet -- curse surcharge is 50 G (50 % of the cursed item only), 210 G before further modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("quotes for a customer with exactly 2 years with MHPCO -- 20 % loyalty discount applies on the policy base premium");
  it.todo("quotes for a customer with 1 year with MHPCO -- no loyalty discount");
  it.todo("quotes a first insurance -- 10 % initial assessment surcharge on the policy base premium");
  it.todo("quotes a customer's second quote in the scenario -- additional 15 % follow-up contract discount");
  it.todo("quotes a customer's third quote in the scenario -- follow-up contract discount applies again");

  // --- Quote: rounding in the MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) -- premium 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) -- premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote with an unknown item type (broomstick) -- CLI exits non-zero, error on stderr, no results on stdout");

  // --- Claim: insurance sum and cap per item type (values are independent of premiums) ---
  it.todo("caps a sword policy at 2000 G (insurance value 1000 G x 2)");
  it.todo("caps an amulet policy at 1200 G (insurance value 600 G x 2)");
  it.todo("caps a staff policy at 1600 G (insurance value 800 G x 2)");
  it.todo("caps a potion policy at 800 G (insurance value 400 G x 2)");
  it.todo("caps a rune policy at 500 G (component insurance value 250 G x 2)");
  it.todo("caps a moonstone policy at 500 G (component insurance value 250 G x 2)");
  it.todo("caps a sword + amulet policy at 3200 G (insurance sum 1600 G)");
  it.todo("caps a sword + 3 runes policy at 3500 G (insurance sum 1750 G; the block discount affects the premium only)");
  it.todo("caps a cursed sword policy at 2000 G -- premium modifiers do not raise the cap");
  it.todo("caps a two-sword policy at 4000 G (insurance sum 2000 G)");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out 400 G for 500 G damage to a regular steel sword with enchantment 3 (full reimbursement minus 100 G deductible)");
  it.todo("pays out 100 G for 200 G damage to a rune (no enchantment level or material, so no special clause)");
  it.todo("pays out 0 G when the damage amount is below the 100 G deductible");
  it.todo("pays out 600 G for a dragon attack damaging a sword (500 G) and an amulet (300 G) -- deductible applies once per damaged item");
  it.todo("treats two sword damage entries on a two-sword policy as separate damages, each with its own deductible");

  // --- Claim: special clauses ---
  it.todo("pays out 400 G for 1000 G damage to a steel sword with enchantment 9 (50 % clause first, then deductible)");
  it.todo("pays out 700 G for 800 G damage to a dragon-material sword with enchantment 5 (full reimbursement, then deductible)");
  it.todo("pays out 400 G for 1000 G damage to a dragon-material sword with enchantment 9 (50 % rule wins over dragon material, then deductible)");
  it.todo("pays out 400 G for 1000 G damage to a dragon-material sword with exactly enchantment 8 (threshold is inclusive)");
  it.todo("pays out 650 G for 750 G damage to a steel sword with enchantment 7 (below the 50 % threshold: full reimbursement, then deductible)");

  // --- Claim: rounding in the MHPCO's favor ---
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("reports the remaining cap after a claim -- 1500 G claim on a sword policy pays 1400 G, remaining cap 600 G");
  it.todo("reduces a second 1500 G claim to the remaining cap -- payout 600 G, remaining cap 0 G");

  // --- Claim: rejection ---
  it.todo("rejects a claim for an item that is not part of the policy (amulet damaged when only a sword is insured) -- CLI exits non-zero with an error on stderr");
  it.todo("rejects a claim for a damage entry with an unknown item type -- CLI exits non-zero with an error on stderr");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- CLI exits non-zero with an error on stderr");
  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero with an error on stderr");

  // --- CLI adapter ---
  it.todo("reads a scenario from stdin and writes a results array of the same length and order to stdout");
  it.todo("resolves a claim step's policy field to the zero-based index of the earlier quote step");
});

