export interface Customer {
  yearsWithMHPCO: number;
  previousContracts: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function basePremiumForGroup(type: string, count: number): number {
  if (COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }
  return count * BASE_PREMIUMS[type];
}

export function quote(customer: Customer, items: Item[]): number {
  let policyBasePremium = 0;
  for (const [type, count] of countByType(items)) {
    policyBasePremium += basePremiumForGroup(type, count);
  }
  return policyBasePremium + PROCESSING_FEE;
}
EOF
